    outer = json.load(f)

inner = json.loads(outer['result'])
raw = inner['data']['result']['raw']
lines = raw.split('\n')

# Find all Write tool calls to see what files were modified
print('=== Files Written ===')
for line in lines:
    if not line.strip():
        continue
    try:
        msg = json.loads(line)
        if msg.get('type') == 'assistant':
            content = msg.get('message', {}).get('content', [])
            for c in content:
                if c.get('type') == 'tool_use' and c.get('name') == 'Write':
                    fp = c.get('input', {}).get('file_path', '')
                    print(f'  {fp}')
    except:
        pass

# Count Read calls to images (the context-blowing culprit)
print()
print('=== Image Read calls ===')
img_count = 0
for line in lines:
    if not line.strip():
        continue
    try:
        msg = json.loads(line)
        if msg.get('type') == 'assistant':
            content = msg.get('message', {}).get('content', [])
            for c in content:
                if c.get('type') == 'tool_use' and c.get('name') == 'Read':
                    fp = c.get('input', {}).get('file_path', '')
                    if fp.endswith('.png') or fp.endswith('.pdf'):
                        img_count += 1
                        print(f'  {fp}')
    except:
        pass
print(f'Total image reads: {img_count}')
